// Resumable pattern (pseudo)
let lastFrameId = null;
try {
  for await (const frame of toAsyncIterable(resp.body)) {
    lastFrameId = frame.id || lastFrameId;
    process(frame.payload);
  }
} catch (err) {
  if (isTransient(err)) {
    const resumed = await client.stream({ resume_from: lastFrameId });
    for await (const f of toAsyncIterable(resumed.body)) process(f.payload);
  } else throw err;
}
// toWebReadable example
const readable = toWebReadable(asyncGenerator());
const reader = readable.getReader();
(async function consume(){
  while(true){
    const { done, value } = await reader.read();
    if(done) break;
    console.log('got', value);
  }
})();
